/**
 * Every port-only catalogue, keyed by SPD's language code (`languages.ts`).
 *
 * Assembled here rather than in `index.ts` so tooling can compare the catalogues without
 * importing the `mwg` runtime: `tools/i18nCheck.ts` asserts that each non-English catalogue
 * carries exactly English's key set with exactly its `{placeholder}` tokens, the invariant
 * that silently drifted for five locales before that check existed.
 */
export const PORT_STRINGS: Readonly<Record<string, Readonly<Record<string, string>>>> = {
	en: PORT_STRINGS_EN,
	fr: PORT_STRINGS_FR,
	de: PORT_STRINGS_DE,
	es: PORT_STRINGS_ES,
	pt: PORT_STRINGS_PT,
	it: PORT_STRINGS_IT,
	pl: PORT_STRINGS_PL,
	ru: PORT_STRINGS_RU,
	tr: PORT_STRINGS_TR,
	uk: PORT_STRINGS_UK,
	hu: PORT_STRINGS_HU,
	nl: PORT_STRINGS_NL,
	in: PORT_STRINGS_IN,
	ja: PORT_STRINGS_JA,
	cs: PORT_STRINGS_CS,
	vi: PORT_STRINGS_VI,
	el: PORT_STRINGS_EL,
	ko: PORT_STRINGS_KO,
	zh: PORT_STRINGS_ZH,
};

/**
 * Provenance is deliberately data as well as a nearby comment: tooling and reviewers can
 * distinguish human copy from an MT draft without guessing from the language's SPD status.
 * `machine` means the port-only strings were generated from English and still need native
 * proofreading; it says nothing about SPD's separate `.properties` catalog.
 */
export type PortTranslationOrigin = 'human' | 'machine';
export const PORT_TRANSLATION_ORIGIN: Readonly<Record<string, PortTranslationOrigin>> = {
	en: 'human',
	fr: 'human',
	de: 'machine',
	es: 'machine',
	pt: 'machine',
	it: 'machine',
	pl: 'machine',
	ru: 'machine',
	tr: 'machine',
	uk: 'machine',
	hu: 'machine',
	nl: 'machine',
	in: 'machine',
	ja: 'machine',
	cs: 'machine',
	vi: 'machine',
	el: 'machine',
	ko: 'machine',
	zh: 'machine',
};
